29	## domain/command — commands
30	
31	```java
32	package com.study.app.domain.command;
33	
34	import com.evento.common.modeling.messaging.payload.DomainCommand;
35	
36	public class CreateOrderCommand extends DomainCommand {
37	    private String orderId;
38	    private String description;
39	    private int quantity;
40	
41	    public CreateOrderCommand() {}
42	    public CreateOrderCommand(String orderId, String description, int quantity) {
43	        this.orderId = orderId;
44	        this.description = description;
45	        this.quantity = quantity;
46	    }
47	
48	    @Override
49	    public String getAggregateId() { return orderId; }   // aggregate routing key
50	
51	    public String getOrderId() { return orderId; }
52	    public void setOrderId(String orderId) { this.orderId = orderId; }
53	    public String getDescription() { return description; }
54	    public void setDescription(String description) { this.description = description; }
55	    public int getQuantity() { return quantity; }
56	    public void setQuantity(int quantity) { this.quantity = quantity; }
57	}
58	```
