60	```java
61	package com.study.app.domain.command;
62	
63	import com.evento.common.modeling.messaging.payload.ServiceCommand;
64	
65	public class ConfirmOrderCommand extends ServiceCommand {
66	    private String orderId;
67	
68	    public ConfirmOrderCommand() {}
69	    public ConfirmOrderCommand(String orderId) { this.orderId = orderId; }
70	
71	    @Override
72	    public String getLockId() { return "confirm-" + orderId; }  // optional lock key
73	
74	    public String getOrderId() { return orderId; }
75	    public void setOrderId(String orderId) { this.orderId = orderId; }
76	}
