123	## domain/view — read DTO
124	
125	```java
126	package com.study.app.domain.view;
127	
128	import com.evento.common.modeling.messaging.payload.View;
129	
130	public class OrderView implements View {
131	    private String orderId;
132	    private String description;
133	    private int quantity;
134	    private String status;
135	
136	    public OrderView() {}
137	    public OrderView(String orderId, String description, int quantity, String status) {
138	        this.orderId = orderId;
139	        this.description = description;
140	        this.quantity = quantity;
141	        this.status = status;
142	    }
