370	```java
371	package com.study.app.command;
372	
373	import com.evento.common.messaging.gateway.CommandGateway;
374	import com.evento.common.modeling.annotations.component.Saga;
375	import com.evento.common.modeling.annotations.handler.SagaEventHandler;
376	import com.study.app.domain.command.ConfirmOrderCommand;
377	import com.study.app.domain.event.OrderConfirmedEvent;
378	import com.study.app.domain.event.OrderCreatedEvent;
379	
380	@Saga(version = 1)
381	public class OrderSaga {
382	
383	    // init handler: creates the saga instance and records the association.
384	    @SagaEventHandler(init = true, associationProperty = "orderId")
385	    OrderSagaState on(OrderCreatedEvent e, CommandGateway cg) throws Exception {
386	        var state = new OrderSagaState();
387	        state.setAssociation("orderId", e.getOrderId());   // correlate future events
388	        state.setOrderId(e.getOrderId());
389	        state.setPhase("CREATED");
390	        if (e.getQuantity() > 0) {
391	            cg.send(new ConfirmOrderCommand(e.getOrderId())).get();  // async; block on result
392	            state.setPhase("CONFIRMING");
393	        }
394	        return state;
395	    }
396	
397	    // subsequent event correlated by orderId; ends the saga.
398	    @SagaEventHandler(associationProperty = "orderId")
399	    OrderSagaState on(OrderConfirmedEvent e, OrderSagaState state) {
400	        state.setPhase("CONFIRMED");
401	        state.setEnded(true);   // saga lifecycle complete
402	        return state;
403	    }
404	}
